165	
166	  const audioItems = useMemo(
167	    () => linkedAttachments.filter(isAudioAttachment).map((attachment) => toLibraryListItem(attachment, locale)),
168	    [linkedAttachments, locale],
169	  );
170	
171	  const unusedItems = useMemo(
172	    () => unusedAttachments.map((attachment) => toLibraryListItem(attachment, locale)),
173	    [unusedAttachments, locale],
174	  );
175	
176	  const mediaGroups = useMemo(
177	    () => groupMediaByMonth(mediaItems, locale, t("attachment-library.labels.unknown-date")),
178	    [locale, mediaItems, t],
179	  );
180	  const mediaPreviewItems = useMemo(() => mediaItems.map((item) => item.previewItem), [mediaItems]);
